"""Offline actual-data report; no network, truth toggle belongs to evaluation only."""
from common08 import *
def render(out,data):
 plots={k:dict(metrics=v['metrics'],**read(ROOT/v['path']/'plot_data.json')) for k,v in data['cases'].items()}
 for d in plots.values():
  for k in ['trajectory','status','gnss','maps','commands']:d[k]=d[k][::max(1,len(d[k])//1500)]
 payload=json.dumps(dict(cases=plots,checks=data['checks'],status=data['status'],mode=data['mode']),ensure_ascii=False).replace('</','<\\/')
 page=r'''<!doctype html><html lang="zh"><meta charset="utf-8"><title>S08 GNSS 配准与偏移监督</title><style>
 body{font:16px system-ui;margin:0;background:#101e2b;color:#e3edf4}main{max-width:1260px;margin:auto;padding:25px}h1{font-size:29px}header,p{line-height:1.6;color:#bdd0df}select,button,input{padding:9px;background:#20374b;color:white;border:1px solid #59718a;border-radius:5px}section{padding:18px;background:#162b3d;border-radius:12px;margin:16px 0}canvas{width:100%;background:#f2f6f9;border-radius:8px}#map{height:430px}#chart{height:250px}pre{white-space:pre-wrap;font-size:14px}a{color:#6edac7}.legend span{margin-right:24px}label{margin-right:18px}.cards{display:flex;gap:25px;flex-wrap:wrap}.card{background:#213d51;padding:14px;border-radius:8px}
 </style><main><h1>S08 · GNSS 配准与定位偏移监督</h1><header>实测 Gazebo + 带误差传感器 + RTAB-Map。全局位置参考选择；单天线没有静止航向。图中真值仅来自独立离线评分，未提供给在线控制。<br>位置 P95 目标 ≤0.15 m，航向 P95 ≤0.05 rad。当前是 A 区诊断运动；不代表整张冻结图均达到精度。</header>
 <section><div class="cards" id="summary"></div></section><section><label>案例 <select id="case"></select></label><label><input type="checkbox" id="truth" checked>显示独立真值</label><label><input type="checkbox" id="raw" checked>显示 GNSS / 地图观测</label><br><label>时间 <input type="range" min="0" max="100" value="100" id="time" style="width:65%"></label><span id="ts"></span><p class="legend"><span style="color:#63cfb5">绿色：最终轨迹</span><span style="color:#5baef1">蓝色：地图观测</span><span style="color:#f7bf60">橙色：GNSS 天线（有 0.1m 水平安装偏移）</span><span>灰色：真值</span></p><canvas id="map" width="1180" height="430"></canvas><div id="numbers" class="cards"></div><pre id="state"></pre></section>
 <section><h2>创新与安全动作时间线</h2><p>蓝：GNSS 创新（m）；红虚线：0.15 m 门槛；绿色条：准入，橙色条：确认或停止；紫色：GNSS 接管。下方执行条蓝色为 DRIVE、红色为 STOP；黑线为当前时刻，故障例标出故障和实际停稳时刻。</p><canvas id="chart" width="1180" height="250"></canvas><pre id="metrics"></pre></section><section><h2>证据与范围</h2><p>协方差通过 ENU→map 旋转并叠加配准不确定度；不把地图和其输入里程计视为独立观测反复融合。测试多径、遮挡和地图失配通过已声明的观测接口注入；环境传感器与车辆运动仍由 Gazebo 实际运行。配准控制点是仿真场地测量先验，真实场地需实测。</p><div id="links"></div><p><a href="result.json">本轮完整指标与命令</a> · 用户人工状态 NOT_CHECKED</p></section></main><script>
 const data=PAYLOAD,$=id=>document.getElementById(id),names=Object.keys(data.cases);for(const n of names){let o=document.createElement('option');o.textContent=n;$('case').append(o)}
 $('summary').innerHTML='<div class="card">'+(data.mode==='demo'?'单例演示':'正式验收')+' <b>'+data.status+'</b></div>'+Object.entries(data.checks).map(([k,v])=>'<div class="card">'+k+' <b>'+v+'</b></div>').join('');
 const map=$('map'),chart=$('chart'),ctx=map.getContext('2d'),cc=chart.getContext('2d');
 function draw(){if(!names.length){$('state').textContent='本轮尚无完成的仿真案例，请查看 result.json 中断或失败原因。';return;}const d=data.cases[$('case').value],end=Math.max(...d.status.map(x=>x.t)),time=end*Number($('time').value)/100;let s=d.status.filter(x=>x.t<=time).at(-1)||d.status[0];$('ts').textContent=time.toFixed(1)+' s';let label={INITIALIZING:'等待地图航向和 GNSS 一致性',CONFIRMING:'已收到观测，正在等待连续证据与停车确认',TRUSTED_MAP:'地图为主，GNSS 独立一致',MAP_ONLY:'GNSS 不合格，地图降速维持',GNSS_ONLY:'GNSS 约束位置，航向只短时传播',STOPPED:'停止运动，等待恢复或重新准入'};let command=d.commands.filter(x=>x.t<=time).at(-1);$('numbers').innerHTML=[['位置 P95',(d.metrics.xy_p95_m??0).toFixed(4)+' m'],['航向 P95',(d.metrics.yaw_p95_rad??0).toFixed(4)+' rad'],['准入占比',(100*d.metrics.admission_fraction).toFixed(1)+'%']].map(([k,v])=>'<div class="card">'+k+' · '+v+'</div>').join('');$('state').textContent=(label[s.state]||s.state)+'\n实际驱动请求：'+(command?command.mode+' / v='+command.v+' m/s, ω='+command.w+' rad/s':'等待')+'\n'+JSON.stringify({t:s.t,state:s.state,source:s.source,reason:s.reason,max_speed:s.max_speed,innovation_m:s.innovation_m,nis:s.nis,heading_age:s.heading_age,plan_revalidation_required:s.plan_revalidation_required},null,2);
 let all=d.trajectory.flatMap(x=>[x.estimate,x.truth]);all.push(...d.maps.filter(x=>x.valid&&x.pose).map(x=>x.pose));if(!all.length)all=[[0,0],[1,1]];let xs=all.map(x=>x[0]),ys=all.map(x=>x[1]),xmin=Math.min(...xs)-.4,xmax=Math.max(...xs)+.4,ymin=Math.min(...ys)-.4,ymax=Math.max(...ys)+.4,scale=Math.min(1060/(xmax-xmin),350/(ymax-ymin));let xy=p=>[70+(p[0]-xmin)*scale,390-(p[1]-ymin)*scale];ctx.clearRect(0,0,1180,430);ctx.fillStyle='#293b4a';ctx.font='14px sans-serif';ctx.fillText('map / m · 固定坐标；不按真值轨迹重新拟合',22,25);
 function line(arr,key,color){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();arr.filter(r=>r.t<=time).forEach((r,i)=>{let p=xy(r[key]);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke()}
 if($('truth').checked)line(d.trajectory,'truth','#84959f');line(d.trajectory,'estimate','#159b7b');if($('raw').checked){for(const [arr,key,color] of [[d.gnss,'antenna','#de922d'],[d.maps,'pose','#287ac1']]){ctx.fillStyle=color;for(const r of arr)if(r.t<=time&&r.valid&&r[key]){let p=xy(r[key]);ctx.beginPath();ctx.arc(...p,2.4,0,7);ctx.fill()}}}
 let last=d.trajectory.filter(r=>r.t<=time).at(-1);if(last){ctx.fillStyle=s.navigation_allowed?'#047e60':'#c1373d';ctx.beginPath();ctx.arc(...xy(last.estimate),6,0,7);ctx.fill()}
 cc.clearRect(0,0,1180,250);const xx=t=>40+t/end*1100,yy=v=>160-Math.min(v,1.6)/1.6*130;cc.strokeStyle='#cb3348';cc.setLineDash([6,5]);cc.beginPath();cc.moveTo(40,yy(.15));cc.lineTo(1140,yy(.15));cc.stroke();cc.setLineDash([]);cc.strokeStyle='#287ac1';cc.beginPath();d.status.forEach((s,i)=>i?cc.lineTo(xx(s.t),yy(s.innovation_m)):cc.moveTo(xx(s.t),yy(s.innovation_m)));cc.stroke();d.status.forEach(s=>{cc.fillStyle=!s.navigation_allowed?'#d08b33':s.state==='GNSS_ONLY'?'#9252b5':'#159b7b';cc.fillRect(xx(s.t),175,3,14)});cc.strokeStyle='#243d52';cc.beginPath();cc.moveTo(xx(time),10);cc.lineTo(xx(time),195);cc.stroke();cc.fillStyle='#293b4a';cc.fillText('0 s',40,16);cc.fillText(end.toFixed(0)+' s',1090,16);cc.fillText('创新上限绘图 1.6 m',750,16);d.commands.forEach(c=>{cc.fillStyle=c.mode==='DRIVE'?'#287ac1':c.mode==='ARM'?'#b58a44':'#c95656';cc.fillRect(xx(c.t),205,3,12)});cc.fillStyle='#293b4a';cc.fillText('监督许可',3,188);cc.fillText('驱动请求',3,217);let stop=d.metrics.physical_stops;if(stop&&stop.fault_to_stop_s!=null){for(const [t,caption] of [[stop.trigger_t,'故障'],[stop.trigger_t+stop.fault_to_stop_s,'停稳']]){cc.strokeStyle='#a42337';cc.beginPath();cc.moveTo(xx(t),25);cc.lineTo(xx(t),220);cc.stroke();cc.fillStyle='#a42337';cc.fillText(caption+' '+t.toFixed(2)+'s',xx(t)-35,caption==='故障'?40:60);}}
 $('metrics').textContent=JSON.stringify(d.metrics,null,2);window.s08Rendered=true;}
 for(const id of ['case','truth','raw'])$(id).onchange=draw;$('time').oninput=draw;draw();
 </script></html>'''
 links=''.join(f'<p>{name}：<a href="{os.path.relpath(ROOT/c["path"]/"metrics.json",out)}">指标</a> · <a href="{os.path.relpath(ROOT/c["path"]/"runtime.json",out)}">实际进程/退出码</a> · <a href="{os.path.relpath(ROOT/c["path"]/"plot_data.json",out)}">时间序列</a></p>' for name,c in data['cases'].items())
 (out/'index.html').write_text(page.replace('PAYLOAD',payload).replace('<div id="links"></div>',links))
